CREATE OR REPLACE FUNCTION public.is_platform_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_is_active() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='super_admin'); $$;
CREATE FUNCTION public.replace_platform_role(_target uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Platform administrator required'; END IF; IF _target=auth.uid() AND _role<>'super_admin' THEN RAISE EXCEPTION 'Cannot demote own administrator account'; END IF; DELETE FROM public.user_roles WHERE user_id=_target; INSERT INTO public.user_roles(user_id,role) VALUES(_target,_role); INSERT INTO public.institution_audit_logs(actor_id,action,target_id,details) VALUES(auth.uid(),'platform_role_changed',_target,jsonb_build_object('role',_role)); END; $$;
REVOKE ALL ON FUNCTION public.replace_platform_role(uuid,public.app_role) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.replace_platform_role(uuid,public.app_role) TO authenticated;
ALTER TABLE public.institutions ADD COLUMN require_member_approval boolean NOT NULL DEFAULT false;
CREATE FUNCTION public.set_company_join_approval(_institution uuid,_required boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_access_institution(_institution,true) THEN RAISE EXCEPTION 'Company administrator required'; END IF; UPDATE public.institutions SET require_member_approval=_required WHERE id=_institution; END; $$;
REVOKE ALL ON FUNCTION public.set_company_join_approval(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.set_company_join_approval(uuid,boolean) TO authenticated;
CREATE FUNCTION public.apply_company_join_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.role='student' AND auth.uid()=NEW.user_id AND NOT public.is_platform_admin() AND EXISTS(SELECT 1 FROM public.institutions WHERE id=NEW.institution_id AND require_member_approval) THEN NEW.active=false; END IF; RETURN NEW; END; $$;
CREATE TRIGGER apply_company_join_approval BEFORE INSERT ON public.institution_memberships FOR EACH ROW EXECUTE FUNCTION public.apply_company_join_approval();
CREATE OR REPLACE FUNCTION public.can_learn_course(_course uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_is_active() AND (public.can_manage_course(_course) OR EXISTS(SELECT 1 FROM public.courses c JOIN public.institutions i ON i.id=c.institution_id JOIN public.enrollments e ON e.course_id=c.id WHERE c.id=_course AND i.status='active' AND c.is_published AND e.user_id=auth.uid() AND e.status IN ('active','completed') AND (NOT i.require_member_approval OR public.has_institution_membership(i.id)))); $$;